@@
 export function normalizeMoncler(url: URL): URL {
+  if (url.hostname === 'www.moncler.com') {
+    // Fix duplicated locale like /en-gb/en-int/
+    const parts = url.pathname.split('/').filter(Boolean);
+    if (parts.length > 1 && /^en-[a-z]{2}$/i.test(parts[0]) && /^en-[a-z]{2}$/i.test(parts[1])) {
+      url.pathname = '/en-int/' + parts.slice(2).join('/') + (url.pathname.endsWith('/') ? '/' : '');
+    }
+    // Ensure at least one locale (use en-int as stable default)
+    if (!/^\/en-[a-z]{2}\//i.test(url.pathname)) {
+      url.pathname = '/en-int' + (url.pathname.startsWith('/') ? '' : '/') + url.pathname;
+    }
+  }
   return url;
 }
